import { auth, cn, handleApiError } from '@/lib'
import { useForm } from '@tanstack/react-form'
import { Link, useNavigate } from '@tanstack/react-router'
import { toast } from 'sonner'
import { useTranslation } from 'react-i18next'
import { z } from 'zod'
import { Field, FieldError, FieldGroup, FieldLabel } from '@/components/ui/field'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Spinner } from '@/components/ui/spinner'
import { AuthFooter } from '@/components/AuthFooter'
import { IconMail, IconLock } from '@tabler/icons-react'
import type { ComponentProps } from 'react'

const signInSchema = z.object({
	email: z.email({ message: 'INVALID_EMAIL' }),
	password: z.string().min(8, { message: 'PASSWORD_TOO_SHORT' }),
})

interface SignInFormProps extends ComponentProps<'div'> {
	callback?: string
	email?: string
}

export function SignInForm({ className, callback, email, ...props }: SignInFormProps) {
	const { t } = useTranslation()
	const navigate = useNavigate()

	const form = useForm({
		defaultValues: { email: email ?? '', password: '' },
		validators: { onChange: signInSchema },
		onSubmit: async form => {
			const result = signInSchema.safeParse(form.value)
			if (!result.success) return

			const { error } = await auth.signIn.email({
				email: result.data.email,
				password: result.data.password,
			})

			if (error) {
				handleApiError(error)
				return
			}

			toast.success(t('auth.signIn.loginSuccess'))

			const redirectTo = callback?.startsWith('/') && !callback.startsWith('//') ? callback : '/dashboard'
			await navigate({ to: redirectTo })
		},
	})

	return (
		<div className={cn('flex flex-col w-full', className)} {...props}>
			<div className="flex flex-col gap-2 mb-8 text-center">
				<h1 className="text-3xl font-semibold text-foreground">{t('auth.signIn.title')}</h1>
				<p className="text-sm text-muted-foreground">{t('auth.signIn.subtitle')}</p>
			</div>

			<form
				className="w-full"
				noValidate
				onSubmit={e => {
					e.preventDefault()
					e.stopPropagation()
					form.handleSubmit()
				}}
			>
				<FieldGroup>
					<form.Field name="email">
						{field => (
							<Field>
								<FieldLabel htmlFor={field.name}>{t('auth.signIn.email')}</FieldLabel>
								<div className="relative">
									<IconMail className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground pointer-events-none" />
									<Input
										id={field.name}
										type="email"
										autoComplete="email"
										value={field.state.value}
										onBlur={field.handleBlur}
										onChange={e => field.handleChange(e.target.value)}
										className="pl-9"
									/>
								</div>
								{field.state.meta.errors[0] && <FieldError>{String(field.state.meta.errors[0]?.message ?? '')}</FieldError>}
							</Field>
						)}
					</form.Field>

					<form.Field name="password">
						{field => (
							<Field>
								<FieldLabel htmlFor={field.name}>{t('auth.signIn.password')}</FieldLabel>
								<div className="relative">
									<IconLock className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground pointer-events-none" />
									<Input
										id={field.name}
										type="password"
										autoComplete="current-password"
										value={field.state.value}
										onBlur={field.handleBlur}
										onChange={e => field.handleChange(e.target.value)}
										className="pl-9"
									/>
								</div>
								{field.state.meta.errors[0] && <FieldError>{String(field.state.meta.errors[0]?.message ?? '')}</FieldError>}
							</Field>
						)}
					</form.Field>

					<form.Subscribe selector={s => [s.canSubmit, s.isSubmitting] as const}>
						{([canSubmit, isSubmitting]) => (
							<Button type="submit" disabled={!canSubmit} className="w-full mt-2">
								{isSubmitting ? <Spinner /> : t('auth.signIn.submit')}
							</Button>
						)}
					</form.Subscribe>
				</FieldGroup>
			</form>

			<div className="flex flex-col items-center gap-2 mt-6 text-sm text-muted-foreground">
				<Link to="/reset-password" className="hover:text-foreground">
					{t('auth.signIn.forgot')}
				</Link>
				<p>
					{t('auth.signIn.noAccount')}{' '}
					<Link to="/sign-up" className="text-primary font-medium hover:underline">
						{t('auth.signIn.signUpLink')}
					</Link>
				</p>
			</div>

			<AuthFooter className="mt-8" />
		</div>
	)
}

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs))
}

/**
 * Serializes search params for URL, converting Date objects to ISO strings.
 * Use this when updating search params to ensure proper URL serialization.
 */
export function serializeSearchParams<T extends Record<string, unknown>>(updates: Partial<T>): Partial<T> {
	const serialized: Record<string, unknown> = {}

	for (const [key, value] of Object.entries(updates)) {
		if (value instanceof Date) {
			serialized[key] = value.toISOString()
		} else {
			serialized[key] = value
		}
	}

	return serialized as Partial<T>
}

/**
 * Creates a search params updater function that automatically serializes Date objects.
 * Use with TanStack Router's navigate function.
 */
export function createSearchParamsUpdater<T extends Record<string, unknown>>(navigate: (options: { search: (prev: T) => T }) => void) {
	return (updates: Partial<T>) => {
		const serialized = serializeSearchParams(updates)
		navigate({ search: prev => ({ ...prev, ...serialized }) })
	}
}

const isFilled = (val: unknown): boolean => {
	if (val === undefined || val === null || val === '') return false
	if (typeof val === 'boolean' || typeof val === 'number') return true
	if (typeof val === 'string') return true
	if (Array.isArray(val)) return val.length > 0
	if (typeof val === 'object') {
		const values = Object.values(val)
		return values.length > 0 && values.every(isFilled)
	}
	return true
}

/**
 * Checks if all required fields defined in a Zod schema are filled.
 * Only validates keys present in the schema's shape, skipping optional fields.
 */
export function validateFieldsFilledWithSchema<T extends { shape: Record<string, { isOptional(): boolean }>; _zod: { output: any } }>(
	value: Record<string, unknown>,
	schema: T,
): value is T['_zod']['output'] {
	for (const key of Object.keys(schema.shape)) {
		if (schema.shape[key].isOptional()) continue
		if (!isFilled(value[key])) return false
	}
	return true
}

/**
 * Generates initials from a name string.
 * Takes first letter of first two words, or first two characters if single word.
 */
export function getInitials(name: string): string {
	const trimmed = name.trim()
	if (!trimmed) return '?'
	return trimmed
		.split(' ')
		.filter(n => n.length > 0)
		.map(n => n[0])
		.join('')
		.toUpperCase()
		.slice(0, 2)
}

type TryCatchResult<T> = { success: true; data: T } | { success: false; error: Error }

export async function tryCatchAsync<T>(fn: () => Promise<T>): Promise<TryCatchResult<T>> {
	try {
		const data = await fn()
		return { success: true, data }
	} catch (error) {
		return { success: false, error: error as Error }
	}
}

export function tryCatch<T>(fn: () => T): TryCatchResult<T> {
	try {
		const data = fn()
		return { success: true, data }
	} catch (error) {
		return { success: false, error: error as Error }
	}
}

export function getAge(birthDate: string | Date): number {
	const birth = typeof birthDate === 'string' ? new Date(birthDate) : birthDate
	const today = new Date()
	let age = today.getFullYear() - birth.getFullYear()
	const monthDiff = today.getMonth() - birth.getMonth()
	if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birth.getDate())) {
		age--
	}
	return age
}

export function formatCpfForDisplay(cpf: string): string {
	const digits = cpf.replace(/\D/g, '')
	if (digits.length !== 11) return cpf
	return `${digits.slice(0, 3)}.${digits.slice(3, 6)}.${digits.slice(6, 9)}-${digits.slice(9, 11)}`
}

