import { getPixelFunnel } from "../client/getPixelFunnel.ts";
import { queryOptions, useQuery } from "@tanstack/react-query";

export const getPixelFunnelQueryKey = (params: GetPixelFunnelQueryParams) => [{ url: '/v1/tracking/tracking/pixel-funnel' }, ...(params ? [params] : [])] as const

export type GetPixelFunnelQueryKey = ReturnType<typeof getPixelFunnelQueryKey>

export function getPixelFunnelQueryOptions(params: GetPixelFunnelQueryParams, config: Partial<RequestConfig> & { client?: typeof fetch } = {}) {

        const queryKey = getPixelFunnelQueryKey(params)
        return queryOptions<GetPixelFunnelQueryResponse, ResponseErrorConfig<Error>, GetPixelFunnelQueryResponse, typeof queryKey>({
         enabled: !!(params),
         queryKey,
         queryFn: async ({ signal }) => {
            config.signal = signal
            return getPixelFunnel(params, config)
         },
        })

}

/**
 * @description Funnel from PAGE_VIEWED → CHECKOUT_COMPLETED (T23 PixelFunnel)
 * {@link /v1/tracking/tracking/pixel-funnel}
 */
export function useGetPixelFunnel<TData = GetPixelFunnelQueryResponse, TQueryData = GetPixelFunnelQueryResponse, TQueryKey extends QueryKey = GetPixelFunnelQueryKey>(params: GetPixelFunnelQueryParams, options: 
{
  query?: Partial<QueryObserverOptions<GetPixelFunnelQueryResponse, ResponseErrorConfig<Error>, TData, TQueryData, TQueryKey>> & { client?: QueryClient },
  client?: Partial<RequestConfig> & { client?: typeof fetch }
}
 = {}) {

         const { query: queryConfig = {}, client: config = {} } = options ?? {}
         const { client: queryClient, ...queryOptions } = queryConfig
         const queryKey = queryOptions?.queryKey ?? getPixelFunnelQueryKey(params)


         const query = useQuery({
          ...getPixelFunnelQueryOptions(params, config),
          queryKey,
          ...queryOptions
         } as unknown as QueryObserverOptions, queryClient) as UseQueryResult<TData, ResponseErrorConfig<Error>> & { queryKey: TQueryKey }

         query.queryKey = queryKey as TQueryKey

         return query

}
