import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import { PixelEventType } from '@bk-dash/contracts-typescript/wire/enums'
import { PixelEventReadRepository } from '../repositories/PixelEventReadRepository'

export const GetPixelFunnelInputSchema = z.object({
	storeIds: z.array(z.uuid()).min(1),
	storeIntegrationIds: z.array(z.uuid()).optional(),
	from: z.date(),
	to: z.date(),
})

const FunnelStageSchema = z.object({
	type: z.enum(PixelEventType),
	count: z.number().int(),
	uniqueSessions: z.number().int(),
	dropOffFromPreviousPercent: z.number().optional(),
})

export const GetPixelFunnelOutputSchema = z.object({
	stages: z.array(FunnelStageSchema),
	conversionRate: z.number(),
})

/**
 * T23 PixelFunnel. Per spec: "Funnel from PageView → CheckoutCompleted —
 * Counts per event type, drop-off % between stages, time window."
 *
 * Funnel stages are ordered canonically (PAGE_VIEWED → PRODUCT_VIEWED →
 * PRODUCT_ADDED_TO_CART → CHECKOUT_STARTED → CHECKOUT_COMPLETED). Stages
 * missing from the data appear as zero-count rows so the UI can render
 * a complete funnel chart.
 */
const FUNNEL_STAGE_ORDER: PixelEventType[] = [
	PixelEventType.PAGE_VIEWED,
	PixelEventType.PRODUCT_VIEWED,
	PixelEventType.PRODUCT_ADDED_TO_CART,
	PixelEventType.CART_VIEWED,
	PixelEventType.CHECKOUT_STARTED,
	PixelEventType.CHECKOUT_CONTACT_INFO_SUBMITTED,
	PixelEventType.CHECKOUT_COMPLETED,
]

@injectable()
export class GetPixelFunnel extends Handler<typeof GetPixelFunnelInputSchema, typeof GetPixelFunnelOutputSchema> {
	readonly name = 'get_pixel_funnel' as const
	readonly inputSchema = GetPixelFunnelInputSchema
	readonly outputSchema = GetPixelFunnelOutputSchema

	constructor(private readonly pixelEvents: PixelEventReadRepository) {
		super()
	}

	protected async handle(input: this['input']): Promise<this['output']> {
		const raw = await this.pixelEvents.aggregateFunnelStages({
			storeIds: input.storeIds,
			storeIntegrationIds: input.storeIntegrationIds,
			from: input.from,
			to: input.to,
		})
		const byType = new Map(raw.map(r => [r.type, r]))

		const stages = FUNNEL_STAGE_ORDER.map((type, idx) => {
			const current = byType.get(type) ?? { type, count: 0, uniqueSessions: 0 }
			if (idx === 0) {
				return { ...current }
			}
			const prev = byType.get(FUNNEL_STAGE_ORDER[idx - 1]!) ?? { count: 0 }
			const dropOff = prev.count > 0 ? ((prev.count - current.count) / prev.count) * 100 : 0
			return { ...current, dropOffFromPreviousPercent: dropOff }
		})

		const top = byType.get(PixelEventType.PAGE_VIEWED)?.count ?? 0
		const bottom = byType.get(PixelEventType.CHECKOUT_COMPLETED)?.count ?? 0
		const conversionRate = top > 0 ? (bottom / top) * 100 : 0

		return { stages, conversionRate }
	}
}

import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { GetPixelFunnel, GetPixelFunnelOutputSchema } from '../usecases/GetPixelFunnel'

export const GetPixelFunnelControllerInputSchema = z.object({
	ctx: z.object({
		user: z.object({ id: z.string() }),
	}),
	query: z.paginatedQuery({
		storeIds: z.stringToArray(z.uuid(), { min: 1 }),
		storeIntegrationIds: z.stringToArray(z.uuid()).optional(),
		from: z.stringToDate(),
		to: z.stringToDate(),
	}),
})

export const GetPixelFunnelControllerOutputSchema = GetPixelFunnelOutputSchema

@injectable()
export class GetPixelFunnelController extends Controller<
	typeof GetPixelFunnelControllerInputSchema,
	typeof GetPixelFunnelControllerOutputSchema
> {
	readonly path = '/tracking/pixel-funnel'
	readonly method = 'get' as const
	readonly description = 'Funnel from PAGE_VIEWED → CHECKOUT_COMPLETED (T23 PixelFunnel)'
	readonly inputSchema = GetPixelFunnelControllerInputSchema
	readonly outputSchema = GetPixelFunnelControllerOutputSchema

	override middlewares = [AuthAccountMiddleware]

	constructor(private query: GetPixelFunnel) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.query.execute({
			storeIds: request.query.storeIds,
			storeIntegrationIds: request.query.storeIntegrationIds,
			from: request.query.from,
			to: request.query.to,
		})
		return { status: HttpStatusCode.OK, data }
	}
}

import type { Transaction } from '@bk-dash/core-typescript'
import { PixelEventType } from '@bk-dash/contracts-typescript/wire/enums'

export interface PixelFunnelQuery {
	storeIds: string[]
	storeIntegrationIds?: string[]
	from: Date
	to: Date
}

export interface PixelFunnelStage {
	type: PixelEventType
	count: number
	uniqueSessions: number
}

/**
 * Read-only repository for the pixel_events table. TS never writes here
 * (Go owns ingest); Tracking BC's queries select aggregations + grouped
 * counts for the funnel + future per-product attribution views.
 */
export abstract class PixelEventReadRepository {
	abstract aggregateFunnelStages(query: PixelFunnelQuery, tx?: Transaction): Promise<PixelFunnelStage[]>
}
